async function summarize(id, depth=3) {
  const n = await figma.getNodeByIdAsync(id);
  if (!n) return {id, error:'not found'};
  const out = {id:n.id, name:n.name, type:n.type, w:Math.round(n.width), h:Math.round(n.height)};
  if ('cornerRadius' in n) out.r = n.cornerRadius;
  if ('fills' in n) out.fills = JSON.stringify(n.fills).slice(0,400);
  if ('componentProperties' in n) out.props = n.componentProperties;
  if ('characters' in n) { out.chars = n.characters; out.font = n.fontName; out.size = n.fontSize; }
  if ('children' in n && depth>0) out.children = await Promise.all(n.children.map(c=>summarize(c.id, depth-1)));
  return out;
}
