async function setCard(inst,{imgId,cat,name,rating,fav}){
  inst.findOne(n=>n.name==='Favourite'); // noop
  const texts=inst.findAll(n=>n.type==='TEXT');
  // texts: cat(11px), name(15), rating(13)
  const catT=texts.find(t=>t.fontSize===11); const nameT=texts.find(t=>t.fontSize===15); const rateT=texts.find(t=>t.fontSize===13);
  catT.characters=cat; nameT.characters=name; rateT.characters=rating;
  const favBg=inst.findOne(n=>n.name==='Favourite');
  const heart=inst.findAll(n=>n.type==='INSTANCE').find(i=>i.absoluteBoundingBox && Math.round(i.width)===15);
  function paintHeart(color,bgFill,stroke){
    favBg.fills=[{type:'SOLID',color:bgFill}];
    favBg.strokes= stroke?[{type:'SOLID',color:stroke}]:[]; favBg.strokeWeight=1;
    const paint=(n)=>{ if(['VECTOR','ELLIPSE','RECTANGLE','BOOLEAN_OPERATION','POLYGON','STAR','LINE'].includes(n.type)){ try{ if(n.fills&&n.fills.length)n.fills=[{type:'SOLID',color}]; if(n.strokes&&n.strokes.length)n.strokes=[{type:'SOLID',color}]; }catch(e){} } if('children'in n)n.children.forEach(paint); };
    paint(heart);
  }
  return {catT,nameT};
}

