async function chipAL(name, selected, txt){
  const c=figma.createComponent(); c.name=name;
  c.layoutMode='HORIZONTAL'; c.primaryAxisSizingMode='AUTO'; c.counterAxisSizingMode='FIXED';
  c.primaryAxisAlignItems='CENTER'; c.counterAxisAlignItems='CENTER';
  c.paddingLeft=18; c.paddingRight=18;
  c.fills=[{type:'SOLID',color:selected?RED:WHITE}];
  if(!selected){ c.strokes=[{type:'SOLID',color:LINE}]; c.strokeWeight=1; }
  c.cornerRadius=18;
  const t=await T(c,txt,{size:14,style:selected?'SemiBold':'Medium',color:selected?WHITE:BROWN});
  c.resize(c.width,36);
  c.counterAxisSizingMode='FIXED'; c.resize(c.width,36);
  ds.appendChild(c);
  return c;
}
