  const img=await imgFit(imgId,120,104); img.x=(179-img.width)/2; img.y=12+(104-img.height)/2; c.appendChild(img);
  const ct=await T(c,cat,{x:16,y:124,size:11,style:'Medium',color:SUB}); ct.letterSpacing={unit:'PIXELS',value:0.5};
  await T(c,nm,{x:16,y:142,w:147,size:15,style:'SemiBold',color:BROWN});
  const badge=await inst('2006:45'); badge.x=16; badge.y=186; c.appendChild(badge);
  const val=badge.findOne(n=>n.type==='TEXT'); if(val) val.characters=rating;
  const favBg=figma.createEllipse(); favBg.resize(32,32); favBg.x=179-16-32; favBg.y=184; favBg.name='Favourite';
  favBg.fills=[{type:'SOLID',color:fav?RED:WHITE}];
  if(!fav){ favBg.strokes=[{type:'SOLID',color:LINE}]; favBg.strokeWeight=1; }
  c.appendChild(favBg);
  const hi=await iconInst('1:343',15,fav?WHITE:FAINT); hi.x=179-16-32+8.5; hi.y=184+8.5; c.appendChild(hi);
  c.x=24; c.y=8; ds.appendChild(c);
