  if(t.width>maxW-28){ t.resize(maxW-28,t.height); }
  const bg=c.findOne(n=>n.name==='Bg');
  const newH=t.height+24; bg.resize(t.width+28,newH); c.resize(t.width+28,newH);
  return c;
}

