async function dump(id, d=4){
  const n=await figma.getNodeByIdAsync(id);
  const o={id:n.id,name:n.name,type:n.type};
  if(n.type==='TEXT') o.chars=n.characters;
  if(d>0&&'children'in n) o.children=await Promise.all(n.children.map(c=>dump(c.id,d-1)));
  return o;
}
return JSON.stringify(await dump('2019:82'));

